function validate([colors, neededTime]) {
  if (typeof colors !== 'string' || !Array.isArray(neededTime)) return 'colors is a string and neededTime an array.';
  if (colors.length !== neededTime.length) return 'colors and neededTime must have the same length.';
  if (colors.length < 1 || colors.length > 100000) return 'There are 1 to 10^5 balloons.';
  if (!/^[a-z]+$/.test(colors)) return 'colors contains only lowercase English letters.';
  if (neededTime.some(t => !Number.isInteger(t) || t < 1 || t > 10000)) return 'Each neededTime is an integer from 1 to 10^4.';
  return null;
}

