function minCost(colors, neededTime) {
  // DP over the color of the last balloon kept (key '' means none kept yet): each balloon is either removed or kept.
  let costs = new Map([['', 0]]);
  for (let i = 0; i < colors.length; i++) {
    const next = new Map();
    const offer = (key, cost) => { if (!next.has(key) || cost < next.get(key)) next.set(key, cost); };
    for (const [last, cost] of costs) {
      offer(last, cost + neededTime[i]);
      if (last !== colors[i]) offer(colors[i], cost);
    }
    costs = next;
  }
  return Math.min(...costs.values());
}

