function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const letters = size === 'large' && rand() < 0.3 ? 26 : 1 + Math.floor(rand() * 3);
  const top = rand() < 0.5 ? 10000 : 10;
  let colors = '';
  const neededTime = [];
  for (let i = 0; i < n; i++) {
    colors += String.fromCharCode(97 + Math.floor(rand() * letters));
    neededTime.push(1 + Math.floor(rand() * top));
  }
  return [colors, neededTime];
}
